#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_channel1: Mutex<Option<bool>> = Mutex::new(None);
  pub static ref IN_channel2: Mutex<Option<bool>> = Mutex::new(None);
  pub static ref IN_channel3: Mutex<Option<bool>> = Mutex::new(None);
  pub static ref IN_channel4: Mutex<Option<bool>> = Mutex::new(None);
  pub static ref OUT_actuate: Mutex<Option<bool>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_channel1.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_channel2.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_channel3.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_channel4.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_actuate.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_channel1(value: *mut bool) -> bool
{
  unsafe {
    let guard = IN_channel1.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn get_channel1_num_invalid() -> u64
{
  return 0;
}

